import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';
import { AuthService } from 'src/app/service/auth.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent implements OnInit {

  jobSeeker!: jobSeeker;

  // Editable form fields, kept separate from the loaded model until saved.
  firstName = '';
  lastName = '';
  email = '';
  location = '';
  skillsText = '';

  loading = true;
  loadError = '';

  saving = false;

  resumeUrl: string | undefined;
  uploadingResume = false;
  resumeError = '';
  resumeJustUpdated = false;

  constructor(
    private jobSeekerService: JobseekerService,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getJobSeekerById();
  }

  getJobSeekerById(): void {
    const id = Number(localStorage.getItem('id'));
    this.loading = true;
    this.loadError = '';

    this.jobSeekerService.getJobSeekerById(id).subscribe({
      next: (result) => {
        this.jobSeeker = result;
        this.firstName = result.firstName || '';
        this.lastName = result.lastName || '';
        this.email = result.email || '';
        this.location = result.location || '';
        this.skillsText = (result.skills || []).join(', ');
        this.resumeUrl = result.resumeUrl;
        this.loading = false;
      },
      error: (err) => {
        console.log(err);
        this.loading = false;
        this.loadError = 'Could not load your profile. Please refresh the page or try again shortly.';
      }
    });
  }

  save(): void {
    const id = Number(localStorage.getItem('id'));
    const updated: Partial<jobSeeker> = {
      firstName: this.firstName,
      lastName: this.lastName,
      email: this.email,
      location: this.location,
      skills: this.skillsText
        .split(',')
        .map(s => s.trim())
        .filter(s => s.length > 0)
    };

    this.saving = true;
    this.jobSeekerService.updateJobSeeker(id, updated).subscribe({
      next: () => {
        this.saving = false;
        this.router.navigateByUrl('/seeker/profile-jobseeker');
      },
      error: (err) => {
        this.saving = false;
        console.log(err);
        alert('Could not save changes. Please try again.');
      }
    });
  }

  onResumeSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) {
      return;
    }

    if (file.type !== 'application/pdf') {
      this.resumeError = 'Please upload a PDF file.';
      input.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      this.resumeError = 'File is too large — please keep it under 5 MB.';
      input.value = '';
      return;
    }

    const id = Number(localStorage.getItem('id'));
    this.uploadingResume = true;
    this.resumeError = '';
    this.resumeJustUpdated = false;

    this.jobSeekerService.uploadResume(id, file).subscribe({
      next: (result) => {
        this.uploadingResume = false;
        this.resumeUrl = result?.resumeUrl ?? this.resumeUrl;
        this.resumeJustUpdated = true;
        input.value = '';
      },
      error: (err) => {
        this.uploadingResume = false;
        this.resumeError = err.error?.message ?? 'Could not upload your resume. Please try again.';
        console.log(err);
        input.value = '';
      }
    });
  }

  deleteAccount(): void {
    const confirmed = window.confirm(
      'This will permanently delete your account and all of your applications. This cannot be undone. Continue?'
    );
    if (!confirmed) {
      return;
    }

    const id = Number(localStorage.getItem('id'));
    this.jobSeekerService.deleteJobSeeker(id).subscribe({
      next: () => {
        this.authService.logout();
        this.router.navigateByUrl('/');
      },
      error: (err) => {
        console.log(err);
        alert('Could not delete your account right now. Please try again later.');
      }
    });
  }
}
<div class="page">
<app-header variant="seeker"></app-header>
<div class="app-shell">
<app-sidebar variant="seeker"></app-sidebar>
<main class="main">

<div class="page-title">Edit Profile</div>

<p *ngIf="loading" class="muted" style="font-size:13.5px;">Loading your profile&hellip;</p>
<p *ngIf="loadError" style="color:#c0392b;font-size:13.5px;">{{ loadError }}</p>

<div class="form-card" *ngIf="!loading && !loadError">
  <div class="card-row">
    <div class="field"><label>First name</label><input [(ngModel)]="firstName" name="firstName"></div>
    <div class="field"><label>Last name</label><input [(ngModel)]="lastName" name="lastName"></div>
  </div>
  <div class="field"><label>Email</label><input [(ngModel)]="email" name="email"></div>
  <div class="field"><label>Location</label><input [(ngModel)]="location" name="location"></div>
  <div class="field"><label>Skills (comma separated)</label><input [(ngModel)]="skillsText" name="skillsText"></div>
  <div class="form-actions">
    <button class="btn btn-primary" [disabled]="saving" (click)="save()">{{ saving ? 'Saving…' : 'Save changes' }}</button>
    <a routerLink="/seeker/profile-jobseeker" class="btn btn-secondary">Cancel</a>
  </div>
</div>

<div class="form-card" style="margin-top:20px;" *ngIf="!loading && !loadError">
  <h3 style="font-size:14px;margin-bottom:10px;">Resume</h3>

  <div *ngIf="resumeUrl" style="display:flex;justify-content:space-between;align-items:center;padding:12px;border:1px dashed var(--line);border-radius:8px;margin-bottom:14px;">
    <div>
      <div style="font-weight:600;font-size:13.5px;">Resume on file</div>
      <div class="muted" style="font-size:12.5px;">{{ resumeJustUpdated ? 'Updated just now' : 'Uploaded previously' }}</div>
    </div>
    <a [href]="resumeUrl" target="_blank" rel="noopener" class="btn btn-secondary btn-sm">View</a>
  </div>
  <p *ngIf="!resumeUrl" class="muted" style="font-size:13px;margin-bottom:14px;">No resume uploaded yet. Add one so companies can review it when you apply.</p>

  <label for="resumeInput" class="btn btn-secondary" style="cursor:pointer;display:inline-block;">
    {{ resumeUrl ? 'Replace resume (PDF)' : 'Upload resume (PDF)' }}
  </label>
  <input id="resumeInput" type="file" accept="application/pdf" (change)="onResumeSelected($event)" [disabled]="uploadingResume" style="display:none;">

  <p *ngIf="uploadingResume" class="muted" style="font-size:12.5px;margin-top:8px;">Uploading&hellip;</p>
  <p *ngIf="resumeError" style="color:#c0392b;font-size:12.5px;margin-top:8px;">{{ resumeError }}</p>
  <p *ngIf="resumeJustUpdated && !uploadingResume && !resumeError" style="color:#2e7d32;font-size:12.5px;margin-top:8px;">Resume updated.</p>
  <p class="muted" style="font-size:11.5px;margin-top:8px;">PDF only, up to 5&nbsp;MB.</p>
</div>

<div class="form-card" style="margin-top:20px;border-color:#e57373;" *ngIf="!loading && !loadError">
  <h3 style="font-size:14px;margin-bottom:8px;color:#c0392b;">Danger zone</h3>
  <p class="muted" style="font-size:12.5px;margin-bottom:12px;">Deleting your account removes your profile and application history permanently.</p>
  <button class="btn btn-outline-danger" (click)="deleteAccount()">Delete my account</button>
</div>

</main>
</div>
</div>
